def comps_of(g,color):
    seen=[[False]*len(g[0]) for _ in g]; res=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==color and not seen[i][j]:
                comp=[]; stack=[(i,j)]; seen[i][j]=True
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==color and not seen[x][y]:
                                seen[x][y]=True; stack.append((x,y))
                res.append(comp)
    return res

def solve(inp,color=7):
    cs=comps_of(inp,color)
    c=max(cs,key=len)
    rs=[a for a,b in c]; cl=[b for a,b in c]
    return [[1 if inp[a][b]==color else 0 for b in range(min(cl),max(cl)+1)] for a in range(min(rs),max(rs)+1)]

